  "{game} community projects": { eng: "{game} community projects", deu: "{game}-Community-Projekte", esp: "Proyectos de la comunidad de {game}", fra: "Projets de la communauté {game}", ita: "Progetti della community di {game}", jpn: "{game} コミュニティプロジェクト", kor: "{game} 커뮤니티 프로젝트", pol: "Projekty społeczności {game}", ptb: "Projetos da comunidade de {game}", rus: "Проекты сообщества {game}", spa: "Proyectos de la comunidad de {game}", tha: "โปรเจกต์ชุมชน {game}", tur: "{game} topluluk projeleri", zhs: "{game} 社区项目", zht: "{game} 社群專案" },
  "Bots, widgets, apps, and tools built with the Spire Codex API by the Slay the Spire 2 community.": { eng: "Bots, widgets, apps, and tools built with the Spire Codex API by the Slay the Spire 2 community.", deu: "Bots, Widgets, Apps und Tools, die die Slay the Spire 2-Community mit der Spire Codex API gebaut hat.", esp: "Bots, widgets, apps y herramientas creados con la API de Spire Codex por la comunidad de Slay the Spire 2.", fra: "Bots, widgets, applications et outils créés avec l'API Spire Codex par la communauté Slay the Spire 2.", ita: "Bot, widget, app e strumenti creati con l'API di Spire Codex dalla community di Slay the Spire 2.", jpn: "Slay the Spire 2コミュニティがSpire Codex APIで作ったボット、ウィジェット、アプリ、ツール。", kor: "Slay the Spire 2 커뮤니티가 Spire Codex API로 만든 봇, 위젯, 앱, 도구.", pol: "Boty, widżety, aplikacje i narzędzia stworzone z użyciem API Spire Codex przez społeczność Slay the Spire 2.", ptb: "Bots, widgets, apps e ferramentas criados com a API do Spire Codex pela comunidade de Slay the Spire 2.", rus: "Боты, виджеты, приложения и инструменты, созданные сообществом Slay the Spire 2 на основе API Spire Codex.", spa: "Bots, widgets, apps y herramientas creados con la API de Spire Codex por la comunidad de Slay the Spire 2.", tha: "บอท วิดเจ็ต แอป และเครื่องมือที่ชุมชน Slay the Spire 2 สร้างด้วย Spire Codex API", tur: "Slay the Spire 2 topluluğunun Spire Codex API ile oluşturduğu botlar, widget'lar, uygulamalar ve araçlar.", zhs: "Slay the Spire 2 社区使用 Spire Codex API 构建的机器人、小组件、应用和工具。", zht: "Slay the Spire 2 社群使用 Spire Codex API 構建的機器人、小工具、應用程式和工具。" },
  "Projects and tools built with the Spire Codex API. Want to add yours? Share it in the": { eng: "Projects and tools built with the Spire Codex API. Want to add yours? Share it in the", deu: "Projekte und Tools, die mit der Spire Codex API gebaut wurden. Deins soll dazu? Teile es im", esp: "Proyectos y herramientas creados con la API de Spire Codex. ¿Quieres añadir el tuyo? Compártelo en el", fra: "Projets et outils créés avec l'API Spire Codex. Vous voulez ajouter le vôtre ? Partagez-le sur le", ita: "Progetti e strumenti creati con l'API di Spire Codex. Vuoi aggiungere il tuo? Condividilo sul", jpn: "Spire Codex APIで作られたプロジェクトとツール。あなたの作品も載せたい場合は、こちらで共有してください：", kor: "Spire Codex API로 만든 프로젝트와 도구. 여러분의 작품을 추가하고 싶다면 여기서 공유하세요:", pol: "Projekty i narzędzia stworzone z użyciem API Spire Codex. Chcesz dodać swój? Podziel się nim na", ptb: "Projetos e ferramentas criados com a API do Spire Codex. Quer adicionar o seu? Compartilhe no", rus: "Проекты и инструменты на основе API Spire Codex. Хотите добавить свой? Поделитесь им в", spa: "Proyectos y herramientas creados con la API de Spire Codex. ¿Quieres añadir el tuyo? Compártelo en el", tha: "โปรเจกต์และเครื่องมือที่สร้างด้วย Spire Codex API อยากเพิ่มของคุณไหม? แชร์ได้ที่", tur: "Spire Codex API ile oluşturulan projeler ve araçlar. Seninkini eklemek ister misin? Şurada paylaş:", zhs: "使用 Spire Codex API 构建的项目和工具。想添加你的作品？请分享到", zht: "使用 Spire Codex API 構建的專案和工具。想加入你的作品？請分享到" },
  "and we'll get it listed here.": { eng: "and we'll get it listed here.", deu: "und wir nehmen es hier auf.", esp: "y lo añadiremos aquí.", fra: "et nous l'ajouterons ici.", ita: "e lo aggiungeremo qui.", jpn: "ここに掲載します。", kor: "여기에 등록해 드립니다.", pol: "a dodamy go tutaj.", ptb: "e vamos listá-lo aqui.", rus: "и мы добавим его сюда.", spa: "y lo añadiremos aquí.", tha: "แล้วเราจะนำมาลงไว้ที่นี่", tur: "biz de buraya ekleyelim.", zhs: "我们会把它列在这里。", zht: "我們會把它列在這裡。" },
  "No projects yet. Be the first!": { eng: "No projects yet. Be the first!", deu: "Noch keine Projekte. Sei der Erste!", esp: "Aún no hay proyectos. ¡Sé el primero!", fra: "Aucun projet pour l'instant. Soyez le premier !", ita: "Ancora nessun progetto. Sii il primo!", jpn: "まだプロジェクトはありません。最初の一人になりましょう！", kor: "아직 프로젝트가 없습니다. 첫 번째가 되어 보세요!", pol: "Brak projektów. Bądź pierwszy!", ptb: "Ainda não há projetos. Seja o primeiro!", rus: "Проектов пока нет. Станьте первым!", spa: "Aún no hay proyectos. ¡Sé el primero!", tha: "ยังไม่มีโปรเจกต์ มาเป็นคนแรกกันเถอะ!", tur: "Henüz proje yok. İlk sen ol!", zhs: "还没有项目。来做第一个吧！", zht: "還沒有專案。來做第一個吧！" },
