  "ILSpy decompiles sts2.dll into ~3,300 C# source files containing all game models": { eng: "ILSpy decompiles sts2.dll into ~3,300 C# source files containing all game models", deu: "ILSpy dekompiliert sts2.dll in ~3.300 C#-Quelldateien mit allen Spielmodellen", esp: "ILSpy descompila sts2.dll en ~3.300 archivos fuente de C# con todos los modelos del juego", fra: "ILSpy décompile sts2.dll en ~3 300 fichiers source C# contenant tous les modèles du jeu", ita: "ILSpy decompila sts2.dll in ~3.300 file sorgente C# contenenti tutti i modelli di gioco", jpn: "ILSpyがsts2.dllを全ゲームモデルを含む約3,300のC#ソースファイルにデコンパイル", kor: "ILSpy가 sts2.dll을 모든 게임 모델이 담긴 약 3,300개의 C# 소스 파일로 디컴파일", pol: "ILSpy dekompiluje sts2.dll do ~3 300 plików źródłowych C# zawierających wszystkie modele gry", ptb: "O ILSpy descompila sts2.dll em ~3.300 arquivos-fonte C# contendo todos os modelos do jogo", rus: "ILSpy декомпилирует sts2.dll в ~3 300 файлов исходного кода C# со всеми игровыми моделями", spa: "ILSpy descompila sts2.dll en ~3.300 archivos fuente de C# con todos los modelos del juego", tha: "ILSpy ถอดรหัส sts2.dll เป็นไฟล์ซอร์ส C# ประมาณ 3,300 ไฟล์ที่มีโมเดลเกมทั้งหมด", tur: "ILSpy, sts2.dll'i tüm oyun modellerini içeren ~3.300 C# kaynak dosyasına çözer", zhs: "ILSpy 将 sts2.dll 反编译为约 3,300 个包含全部游戏模型的 C# 源文件", zht: "ILSpy 將 sts2.dll 反編譯為約 3,300 個包含全部遊戲模型的 C# 原始檔" },
  "Data Parsing": { eng: "Data Parsing", deu: "Daten-Parsing", esp: "Análisis de datos", fra: "Analyse des données", ita: "Parsing dei dati", jpn: "データ解析", kor: "데이터 파싱", pol: "Parsowanie danych", ptb: "Análise de dados", rus: "Разбор данных", spa: "Análisis de datos", tha: "การแยกวิเคราะห์ข้อมูล", tur: "Veri Ayrıştırma", zhs: "数据解析", zht: "資料解析" },
  "17 Python parsers extract structured data from decompiled C# source + localization JSON": { eng: "17 Python parsers extract structured data from decompiled C# source + localization JSON", deu: "17 Python-Parser extrahieren strukturierte Daten aus dem dekompilierten C#-Quellcode und dem Lokalisierungs-JSON", esp: "17 analizadores en Python extraen datos estructurados del código C# descompilado y del JSON de localización", fra: "17 parseurs Python extraient des données structurées du code C# décompilé et du JSON de localisation", ita: "17 parser Python estraggono dati strutturati dal sorgente C# decompilato e dal JSON di localizzazione", jpn: "17個のPythonパーサーがデコンパイルしたC#ソースとローカライズJSONから構造化データを抽出", kor: "17개의 Python 파서가 디컴파일된 C# 소스와 현지화 JSON에서 구조화된 데이터를 추출", pol: "17 parserów w Pythonie wyciąga ustrukturyzowane dane ze zdekompilowanego kodu C# i JSON-a lokalizacji", ptb: "17 parsers em Python extraem dados estruturados do código C# descompilado e do JSON de localização", rus: "17 парсеров на Python извлекают структурированные данные из декомпилированного кода C# и JSON локализации", spa: "17 analizadores en Python extraen datos estructurados del código C# descompilado y del JSON de localización", tha: "พาร์เซอร์ Python 17 ตัวดึงข้อมูลที่มีโครงสร้างจากซอร์ส C# ที่ถอดรหัสแล้วและ JSON แปลภาษา", tur: "17 Python ayrıştırıcısı, derlemesi çözülmüş C# kaynağından ve yerelleştirme JSON'undan yapılandırılmış veri çıkarır", zhs: "17 个 Python 解析器从反编译的 C# 源码和本地化 JSON 中提取结构化数据", zht: "17 個 Python 解析器從反編譯的 C# 原始碼和在地化 JSON 中提取結構化資料" },
